skip={'id','sources','lines','his_words','his_statement','program','output','refined_statement_id'}
def clean(s):
 for a,b in sorted(replacements.items(),key=lambda kv:-len(kv[0])):s=s.replace(a,b)
 s=re.sub(r'\b(Theorem|Théorème|Corollaire|Lemma|Remark|Proposition|Example|Corollary)(?=\d)',r'\1 ',s)
 return s
def walk(v,key=''):
 if key in skip:return v
 if isinstance(v,str):return clean(v)
 if isinstance(v,list):return [walk(x,key) for x in v]
 if isinstance(v,dict):return {k:walk(x,k) for k,x in v.items()}
 return v
for fn in ['items.json','claims.json','problems.json']:
 p=W/fn;p.write_text(json.dumps(walk(json.loads(p.read_text())),ensure_ascii=False,indent=2)+'\n')
for fn in ['readings.tsv']:
 p=W/fn
 with p.open() as f:r=csv.DictReader(f,delimiter='\t');fields=r.fieldnames;rows=list(r)
 with p.open('w') as f:
  w=csv.DictWriter(f,fieldnames=fields,delimiter='\t',lineterminator='\n');w.writeheader();w.writerows({k:(v if k in {'line','scan','cote'} else clean(v)) for k,v in r.items()} for r in rows)
print('Applied explicit prose-spacing corrections; diplomatic quotations, IDs, source paths and computation paths unchanged.')
